export const CALL_PROFILES=[{id:'rodolfo',title:'Rodolfo quiere saludarte',body:'santa-1.wav',music:'musica-1.wav',musicTitle:'A Quiet Christmas Miracle'},{id:'libro',title:'Un nombre en el gran libro',body:'santa-2.wav',music:'musica-2.wav',musicTitle:'A Christmas Orchestral'}];
const exact=s=>s.trim().normalize('NFC').replace(/\s+/g,' ').toLocaleLowerCase('es'),fold=s=>exact(s).normalize('NFD').replace(/[\u0300-\u036f]/g,'');
export function findName(catalog,name){const e=catalog.find(r=>[r.name,...r.aliases||[]].some(s=>exact(s)===exact(name)));if(e)return e;const m=catalog.filter(r=>[r.name,...r.aliases||[]].some(s=>fold(s)===fold(name)));return m.length===1?m[0]:null;}
export function pcm(bytes){const v=new DataView(bytes.buffer,bytes.byteOffset,bytes.byteLength),str=i=>String.fromCharCode(...bytes.subarray(i,i+4));if(str(0)!=='RIFF'||str(8)!=='WAVE')throw new Error('Audio no compatible.');let rate=0,channels=0,bits=0,format=0,data;
for(let i=12;i+8<=bytes.length;){const n=v.getUint32(i+4,true);if(i+8+n>bytes.length)throw new Error('Audio incompleto.');if(str(i)==='fmt '){format=v.getUint16(i+8,true);channels=v.getUint16(i+10,true);rate=v.getUint32(i+12,true);bits=v.getUint16(i+22,true);}if(str(i)==='data')data=bytes.subarray(i+8,i+8+n);i+=8+n+(n%2);}if(format!==1||rate!==44100||channels!==1||bits!==16||!data)throw new Error('El audio debe ser PCM mono a 44.1 kHz.');const d=new DataView(data.buffer,data.byteOffset,data.byteLength),out=new Float32Array(data.length/2);for(let i=0;i<out.length;i++)out[i]=d.getInt16(i*2,true)/32768;return out;}
export function wav(samples,rate=44100){const n=Math.floor(samples.length*rate/44100),out=new Uint8Array(44+n*2),v=new DataView(out.buffer),txt=(i,s)=>{for(let j=0;j<s.length;j++)out[i+j]=s.charCodeAt(j);};txt(0,'RIFF');v.setUint32(4,out.length-8,true);txt(8,'WAVE');txt(12,'fmt ');v.setUint32(16,16,true);v.setUint16(20,1,true);v.setUint16(22,1,true);v.setUint32(24,rate,true);v.setUint32(28,rate*2,true);v.setUint16(32,2,true);v.setUint16(34,16,true);txt(36,'data');v.setUint32(40,n*2,true);for(let i=0;i<n;i++){const pos=i*44100/rate,lo=Math.floor(pos),f=pos-lo,a=samples[lo]||0,b=samples[Math.min(lo+1,samples.length-1)]||0;v.setInt16(44+i*2,Math.round(Math.max(-1,Math.min(1,a+(b-a)*f))*32767),true);}return out;}
export function join(parts){const arrays=parts.map(p=>typeof p==='number'?new Float32Array(Math.round(p*44100)):p),out=new Float32Array(arrays.reduce((n,a)=>n+a.length,0));let at=0;for(const a of arrays){out.set(a,at);at+=a.length;}return out;}
export function mix(voice,music,offset=0){const out=new Float32Array(voice.length),start=Math.round(offset*44100);for(let i=0;i<out.length;i++){const fade=Math.min(1,(out.length-i)/44100),background=music[(start+i)%music.length]||0;out[i]=Math.max(-1,Math.min(1,voice[i]*.88+background*.10*fade));}return out;}
export async function prepareCall(recording,profileId,base,fetcher=fetch,rate=44100){const profile=CALL_PROFILES.find(p=>p.id===profileId);if(!profile||!recording||!/^assets\/nombres\/[a-zA-Z0-9-]+\.wav$/.test(recording.src))throw new Error('Nombre o saludo no disponible.');const get=async path=>{const r=await fetcher(new URL(path,base));if(!r.ok)throw new Error('No se pudo cargar el audio. Revisa tu conexión.');return pcm(new Uint8Array(await r.arrayBuffer()));};const [elf,hello,name,body,music]=await Promise.all(['duende.wav','hola.wav',recording.src,profile.body,profile.music].map((path,i)=>get(i===2?path:'assets/llamadas/'+path)));const speech=join([hello,.10,name,.15,body]);return {intro:wav(mix(elf,music),rate),santa:wav(mix(speech,music,elf.length/44100),rate),nameAt:hello.length/44100+.10,name:recording.name,profile:profile.id};}
